import {Museum} from './world.mjs';
import {ROOMS,EXHIBITS,roomAt,fullName,floorAt} from './layout.mjs';
const $=s=>document.querySelector(s),SAVE='puzzle-pieces-foundation-v1';
let museum,playing=false,active=null,lastRoom='',lastTime=0,saveTime=0,visited=new Set(),lamp=true,sound=false,audio=null,walk={x:0,z:0},sensitivity=.0035;
const start=()=>({x:0,y:0,z:17,yaw:0,pitch:0});let player=start();const keys=new Set();
const names={monitor:'Visitor services',lamp:'The wired lamp',statue:'A Space Held Open',hidden:'Hidden Operators',rebirth:'Days of Rebirth',cross:'Cross/Hatch',map:'Visitor map',east:'Eastern arcade · closed',security:'Security hall · closed',elevators:'Call elevator',stair:'West mezzanine stair'};
function readSave(){try{const s=JSON.parse(localStorage.getItem(SAVE));if(!s||s.version!==1)return null;const p=s.player;if(!p||!['x','y','z','yaw','pitch'].every(k=>Number.isFinite(p[k])))return null;const floor=floorAt(p.x,p.z,p.y);if(floor===null||Math.abs(floor-p.y)>.6)return null;return s;}catch{return null;}}
function save(){if(!playing)return;try{localStorage.setItem(SAVE,JSON.stringify({version:1,player,visited:[...visited],lamp,sensitivity,quality:museum.quality}));}catch{}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function openPanel(kicker,title,html,cls=''){keys.clear();walk={x:0,z:0};$('#touch-stick').style.transform='';$('#panel').className=cls;$('#panel-kicker').textContent=kicker;$('#panel-title').textContent=title;$('#panel-body').innerHTML=html;if(!$('#panel').open)$('#panel').showModal();}
function closePanel(){$('#panel').close();}
$('#close-panel').onclick=closePanel;$('#panel').addEventListener('click',e=>{if(e.target===$('#panel')){const r=$('#panel').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePanel();}});
function enter(resume){const saved=resume&&readSave();player=saved?{...saved.player}:start();visited=new Set(saved?.visited?.filter(id=>ROOMS.some(r=>r.id===id))||['hall']);lamp=saved?.lamp!==false;sensitivity=Math.min(.008,Math.max(.0015,saved?.sensitivity||.0035));museum.setLamp(lamp);museum.setQuality(saved?.quality||museum.quality);if(museum.blocked(player.x,player.z,player.y))player=start();$('#welcome').hidden=true;$('#hud').hidden=false;playing=true;save();toast(matchMedia('(pointer:coarse)').matches?'Move with the left circle. Drag elsewhere to look.':'WASD to walk · drag to look · E to inspect');}
$('#enter').onclick=()=>enter(false);$('#continue').onclick=()=>enter(true);
function inspect(id){
 if(EXHIBITS[id]){const e=EXHIBITS[id];openPanel('EXHIBIT '+e.number,e.name,`<p style="font-family:Arial,sans-serif;font-size:19px;line-height:1.7">${e.description}</p><p class="rule">${id==='hidden'?'Three open rooms':id==='cross'?'One open room · mezzanine':'One open room'}. No works installed.</p>`);return;}
 if(id==='monitor'){openPanel('INFORMATION / CONNECTED DEVICE','Visitor services',`<p>A copper wire leaves the monitor, follows the edge of the desk, and crosses the floor to the old lamp.</p><div class="switch-status"><span><i class="status-light ${lamp?'on':''}"></i>Lamp ${lamp?'on':'off'}</span><button id="lamp-toggle">Switch ${lamp?'off':'on'}</button></div><p class="rule">Museum directory</p><div class="menu-list"><button id="desk-map">View the visitor map →</button></div>`);$('#lamp-toggle').onclick=()=>{lamp=!lamp;museum.setLamp(lamp);save();inspect('monitor');};$('#desk-map').onclick=()=>openMap();return;}
 if(id==='map'){openMap();return;}
 const data={lamp:['A borrowed streetlight','An old lamp has found its way indoors. Its wire runs back to the monitor on the information booth.'],statue:['A Space Held Open','An abstract bronze study. Its loops hold a shape that can never quite be seen all at once.','The hall’s art and statues are display studies. No solution is required.'],stair:['One stair. One side.','Follow the first flight to the turning landing, then double back up the return flight to the west mezzanine and Cross/Hatch. The east mezzanine is closed. There is no bridge across the hall.'],east:['Eastern Arcade','The doors are locked. This wing will open in a later chapter.'],security:['Security Hall','Staff access is closed. The security rooms and their opening condition belong to a later stage.'],elevators:['Service suspended','The call plate remains dark. The elevators are not operating. The public stair reaches the west mezzanine.']};
 const d=data[id];if(d)openPanel(id==='elevators'?'PUBLIC ELEVATORS':'THE MUSEUM',d[0],`<p>${d[1]}</p>${d[2]?`<p class="rule">${d[2]}</p>`:''}`);
}
$('#interact').onclick=()=>active&&inspect(active.id);
let mapFloor=0;
function openMap(floor=player.y>4?1:0){mapFloor=floor;const current=roomAt(player.x,player.z,player.y);const list=ROOMS.filter(r=>(floor?r.floor>0:r.floor===0));openPanel('VISITOR INFORMATION','The museum plan',`<div class="map-tabs"><button data-floor="0" class="${floor===0?'active':''}">00 / Ground</button><button data-floor="1" class="${floor===1?'active':''}">01 / Mezzanine</button></div><div class="map-layout"><div><img class="map-image" src="docs/floor-plans/option-a-${floor?'upper':'ground'}.svg" alt="Museum floor plan. Open galleries lie west and north of the main hall; closed routes lie east and south."><div class="map-position">You are in ${fullName(current)} · ${current.code}</div></div><div><p class="map-note">Quick visit</p><div class="map-directory">${list.map(r=>`<button data-room="${r.id}" ${r.locked?'disabled':''}>${fullName(r)}<small>${r.code} · ${r.locked?'Closed':visited.has(r.id)?'Visited':'Open'}</small></button>`).join('')}</div><p class="map-note quiet">Choose an open space to visit it. The marked closures stay locked.</p></div></div>`,'map-dialog');$('#panel-body').querySelectorAll('[data-floor]').forEach(b=>b.onclick=()=>openMap(Number(b.dataset.floor)));$('#panel-body').querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>{const r=ROOMS.find(r=>r.id===b.dataset.room);if(!r?.spawn||r.locked)return;const [x,y,z]=r.spawn;player={x,y,z,yaw:r.id==='hall'?0:r.id==='west'?0:r.id==='ch1'?PI/2:0,pitch:0};if(museum.blocked(x,z,y)){toast('That destination is temporarily unavailable.');player=start();}visited.add(r.id);save();closePanel();});}
const PI=Math.PI;$('#map-btn').onclick=()=>openMap();
function help(){openPanel('A VISITOR’S GUIDE','Take your time.',`<p><strong>Desktop:</strong> W A S D or ↑ ↓ to walk. Drag the scene to look. ← → turn. Shift walks faster. E inspects the object in front of you. M opens the map. Escape opens or closes the menu.</p><p><strong>Touch:</strong> Use the left circle to walk. Drag anywhere else in the scene to look. Tap the inspection button when it appears.</p><p>The room and exhibit name stay at the top. Open the map for the floor plan or a quick visit to an open room.</p><p class="rule">This first visit is an architectural foundation. The exhibit rooms are deliberately empty; no answers, keys, or secret unlocks are required.</p><div class="menu-list"><button id="help-return">Return to the museum →</button></div>`);$('#help-return').onclick=closePanel;}
$('#help-btn').onclick=help;
function menu(){openPanel('PUZZLE PIECES','Your visit',`<div class="menu-list"><button id="resume">Continue exploring →</button><button id="menu-map">Museum map</button><button id="menu-help">How to move</button><button id="menu-sound">Ambient sound: ${sound?'on':'off'}</button><button id="menu-fullscreen">Toggle fullscreen</button><a href="docs/" target="_blank" rel="noopener">Design notebook ↗</a><button id="return-hall">Return to the main hall</button><button id="main-menu">Main menu</button></div><p class="rule"><label for="graphics">Graphics quality</label><select id="graphics" ${museum.planView?'disabled':''}><option value="economy" ${museum.quality==='economy'?'selected':''}>Economy — lighter rendering</option><option value="balanced" ${museum.quality==='balanced'?'selected':''}>Balanced</option><option value="high" ${museum.quality==='high'?'selected':''}>High — sharper detail</option></select><span class="quiet">${museum.planView?'Plan view is active because 3D is unavailable in this browser.':'Choose Economy if movement feels slow on your device.'}</span></p><p class="rule"><label for="sensitivity">Look sensitivity</label><input id="sensitivity" type="range" min="0.0015" max="0.008" step="0.0005" value="${sensitivity}"></p><p class="quiet">Your position is saved in this browser.</p>`);$('#resume').onclick=closePanel;$('#menu-map').onclick=()=>openMap();$('#menu-help').onclick=help;$('#menu-sound').onclick=()=>{toggleSound();menu();};$('#menu-fullscreen').onclick=fullscreen;$('#return-hall').onclick=()=>{player=start();save();closePanel();};$('#main-menu').onclick=()=>{save();playing=false;closePanel();$('#hud').hidden=true;$('#welcome').hidden=false;$('#continue').hidden=false;};$('#graphics').onchange=e=>{museum.setQuality(e.target.value);save();};$('#sensitivity').oninput=e=>{sensitivity=Number(e.target.value);save();};}
$('#menu-btn').onclick=menu;
function toggleSound(){sound=!sound;try{if(!audio){audio=new (window.AudioContext||window.webkitAudioContext)();const gain=audio.createGain();gain.gain.value=.012;gain.connect(audio.destination);for(const hz of [65.4,98,130.8]){const osc=audio.createOscillator();osc.frequency.value=hz;osc.type='sine';osc.connect(gain);osc.start();}}sound?audio.resume():audio.suspend();}catch{sound=false;toast('Ambient sound is unavailable in this browser.');}$('#sound-btn').textContent=sound?'Sound on':'Sound off';$('#sound-btn').setAttribute('aria-pressed',String(sound));}
$('#sound-btn').onclick=toggleSound;
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('Use your browser’s full-screen view.');}catch{toast('Fullscreen is unavailable in this browser.');}}
$('#fullscreen-btn').onclick=fullscreen;
window.addEventListener('keydown',e=>{if(!playing)return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(e.key))e.preventDefault();if(e.key==='Escape'){if(!$('#panel').open){e.preventDefault();menu();}return;}if($('#panel').open)return;const k=e.key.toLowerCase();if(k==='m'){openMap();return;}if(k==='e'&&active){inspect(active.id);return;}keys.add(k);});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();walk={x:0,z:0};save();});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();walk={x:0,z:0};save();}});
let lookPointer=null,lookStart=null,totalDrag=0;const canvas=$('#world');canvas.addEventListener('pointerdown',e=>{if(!playing||$('#panel').open)return;lookPointer=e.pointerId;lookStart={x:e.clientX,y:e.clientY};totalDrag=0;canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(e.pointerId!==lookPointer||!lookStart)return;const dx=e.clientX-lookStart.x,dy=e.clientY-lookStart.y;totalDrag+=Math.abs(dx)+Math.abs(dy);player.yaw-=dx*sensitivity;player.pitch=Math.max(-1.15,Math.min(1.15,player.pitch-dy*sensitivity));lookStart={x:e.clientX,y:e.clientY};});function releaseLook(e){if(e.pointerId!==lookPointer)return;if(totalDrag<7&&active&&playing&&!$('#panel').open)inspect(active.id);lookPointer=null;lookStart=null;}canvas.addEventListener('pointerup',releaseLook);canvas.addEventListener('pointercancel',()=>{lookPointer=null;lookStart=null;});
let stickPointer=null;const stick=$('#touch-move');function stickUpdate(e){const r=stick.getBoundingClientRect(),dx=e.clientX-r.x-r.width/2,dy=e.clientY-r.y-r.height/2,len=Math.hypot(dx,dy),scale=Math.min(1,36/Math.max(len,1));walk={x:dx*scale/36,z:dy*scale/36};$('#touch-stick').style.transform=`translate(${dx*scale}px,${dy*scale}px)`;}stick.onpointerdown=e=>{e.preventDefault();stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);stickUpdate(e);};stick.onpointermove=e=>{if(e.pointerId===stickPointer)stickUpdate(e);};stick.onpointerup=stick.onpointercancel=()=>{stickPointer=null;walk={x:0,z:0};$('#touch-stick').style.transform='';};
function frame(time){requestAnimationFrame(frame);if(!museum||document.hidden)return;const dt=Math.min((time-lastTime)/1000,.04);lastTime=time;if(playing){if(!$('#panel').open){let forward=(keys.has('w')||keys.has('arrowup')?1:0)-(keys.has('s')||keys.has('arrowdown')?1:0)-walk.z,side=(keys.has('d')?1:0)-(keys.has('a')?1:0)+walk.x;player.yaw+=((keys.has('arrowleft')?1:0)-(keys.has('arrowright')?1:0))*dt*1.5;const len=Math.max(1,Math.hypot(forward,side)),speed=dt*(keys.has('shift')?5.6:3.7);museum.move(player,(-Math.sin(player.yaw)*forward+Math.cos(player.yaw)*side)/len*speed,(-Math.cos(player.yaw)*forward-Math.sin(player.yaw)*side)/len*speed);active=museum.focus();$('#interact').hidden=!active;if(active)$('#interact-label').textContent=names[active.id]||'Inspect';}else $('#interact').hidden=true;
  const r=roomAt(player.x,player.z,player.y);if(r.id!==lastRoom){lastRoom=r.id;visited.add(r.id);$('#loc-exhibit').textContent=r.exhibit?'EXHIBIT '+EXHIBITS[r.exhibit].number+' / '+EXHIBITS[r.exhibit].name.toUpperCase():'THE MUSEUM';$('#loc-room').textContent=r.name;$('#floor-label').innerHTML=player.y>4?'MEZZANINE <b>01</b>':'GROUND FLOOR <b>00</b>';}
  museum.render(player);if(time-saveTime>2000){saveTime=time;save();}
 }else museum.render({x:4.8,y:.08,z:19,yaw:.14+Math.sin(time*.000025)*.025,pitch:.04});}
try{museum=new Museum(canvas);$('#loading').hidden=true;$('#welcome').hidden=false;$('#continue').hidden=!readSave();$('#view-mode').hidden=!museum.planView;if(museum.planView){$('#reticle').hidden=true;$('.edition').textContent='PLAN VIEW · 3D IS UNAVAILABLE IN THIS BROWSER';}requestAnimationFrame(frame);}catch(error){console.error(error);$('#loading').hidden=true;$('#failure').hidden=false;$('#failure-message').textContent='The museum could not initialize its drawing surface. You can still read the plans and documentation below.';}
window.addEventListener('pagehide',save);
